// schema.prisma
model User {
  id     Int     @id @default(autoincrement())
  email  String  @unique
  orders Order[]
}
model Order {
  id     Int  @id @default(autoincrement())
  total  Int
  user   User @relation(fields: [userId], references: [id])
  userId Int
}

// app code: fully typed
const user = await prisma.user.findUnique({ where: { email: "ada@example.com" }, include: { orders: true } });
